#!/usr/bin/env bash

# Reproduce bugs in parallel from log files generated by syzkaller.
#
# usage:
#   bash scripts/repro.sh -c configs/repro/reprosh.cfg [-j 8]
#
# kill all repro jobs:
#   pkill repro.sh; pkill syz-repro

set -euo pipefail

REPRO_SH_CONFIG_PATH=
JOBS=8

print_help() {
    echo "usage: $0 [ARGS]"
    echo "  args (required):"
    echo "    -c, --config <CONFIG> path to the config file for repro.sh (see configs/repro/reprosh.cfg)"
    echo "  args (optional):"
    echo "    -j, --jobs <JOBS>     number of parallel reproduce jobs (default: 8)"
    echo "    -h, --help            print help message"
}

while [[ $# -gt 0 ]]; do
    case $1 in
    -c | --config)
        REPRO_SH_CONFIG_PATH=$2
        shift 2
        ;;
    -j | --jobs)
        JOBS=$2
        shift 2
        ;;
    -h | --help)
        print_help
        exit 0
        ;;
    *)
        echo "unknown arg: $1"
        exit 1
        ;;
    esac
done

if [[ -z "$REPRO_SH_CONFIG_PATH" ]]; then
    echo "Error: Missing required -c/--config argument."
    print_help
    exit 1
fi

mapfile -t LOGS < <(jq -r .logs[] "$REPRO_SH_CONFIG_PATH")
mapfile -t DONE < <(jq -r .done[] "$REPRO_SH_CONFIG_PATH")
for LOG in "${LOGS[@]}"; do
    if [[ " ${DONE[*]} " == *" $LOG "* ]]; then
        echo "skip repro for $LOG since it's already done"
        continue
    fi

    REPRO_JOBS=$(pgrep -c syz-repro || true)
    while [[ $REPRO_JOBS -ge $JOBS ]]; do
        sleep 1m
        REPRO_JOBS=$(pgrep -c syz-repro || true)
    done

    LOG_NAME=$(basename "$LOG")
    LOG_DIR=$(dirname "$LOG")
    LOG_HASH=$(basename "$LOG_DIR")

    echo "reproducing $LOG ..."
    WORKDIR=$(dirname "$(dirname "$LOG_DIR")")/repro/$LOG_HASH/$LOG_NAME
    SYZKALLER_CONFIG_PATH=$(jq -r .config "$REPRO_SH_CONFIG_PATH")
    SYZKALLER=$(jq -r .syzkaller "$SYZKALLER_CONFIG_PATH")
    mkdir -p "$WORKDIR"
    jq ".vm.count = 1" "$SYZKALLER_CONFIG_PATH" >"$WORKDIR/repro.cfg"
    nohup "$SYZKALLER/bin/syz-repro" \
        -config="$WORKDIR/repro.cfg" \
        -output="$WORKDIR/repro.syz" \
        -crepro="$WORKDIR/repro.c" "$LOG" >"$WORKDIR/repro.log" 2>&1 &
done

REPRO_JOBS=$(pgrep -c syz-repro || true)
while [[ $REPRO_JOBS -gt 0 ]]; do
    sleep 30s
    REPRO_JOBS=$(pgrep -c syz-repro || true)
done
echo "all repro tasks done!"
